DROP TABLE IF EXISTS `schedule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `schedule` (
  `train_no` int NOT NULL,
  `station_no` int NOT NULL,
  `station_code` varchar(10) NOT NULL,
  `distance_from_origin` decimal(6,0) DEFAULT NULL,
  `arrival_day` tinyint DEFAULT NULL,
  `arrival_time` time DEFAULT NULL,
  `departure_day` tinyint DEFAULT NULL,
  `departure_time` time DEFAULT NULL,
  PRIMARY KEY (`train_no`,`station_no`),
  KEY `station_code` (`station_code`),
  CONSTRAINT `schedule_ibfk_1` FOREIGN KEY (`train_no`) REFERENCES `trains` (`train_no`),
  CONSTRAINT `schedule_ibfk_2` FOREIGN KEY (`station_code`) REFERENCES `stations` (`station_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
